//! 🧵️ Vector admission extends the common original typed-child read capability.
use super::child_read::{ChildReadRegistration,ChildReadCapability,ChildReadStamp,ChildReadSourceCustody};
use semio_framework_value::{ValueError,ValueRefusalKind,RetirementDemand,retained_clone::{RetainedCloneGrant,RetainedCloneProgress,retained_clone_grant_admits},retirement::RetireOwned};
use semio_framework_io_ports::{EmbeddedChildAdmitterV1,EmbeddedChildVectorSourceV1,ChildAdmissionAddress};
fn refusal(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
pub struct ChildVectorReadRegistration<S>{pub native:ChildReadRegistration<S>,pub admission:&'static dyn EmbeddedChildAdmitterV1,pub vector:&'static dyn EmbeddedChildVectorSourceV1}
impl<S> ChildVectorReadRegistration<S>{pub const fn new(identity:ChildReadCapability,admission:&'static dyn EmbeddedChildAdmitterV1,vector:&'static dyn EmbeddedChildVectorSourceV1)->Self{Self{native:ChildReadRegistration::new(identity),admission,vector}}}
impl<S:RetireOwned+::semio_os_kernel::StoreState> ChildVectorReadRegistration<S>{pub fn admission_provider<'a>(&'static self,custody:&'a ChildReadSourceCustody<S>,ordinal:usize,g:RetainedCloneGrant)->Result<(ChildVectorAdmissionProvider<'a,S>,RetainedCloneProgress),ValueError>{ChildVectorAdmissionProvider::admit(custody,self,ordinal,g)}}
pub type ChildVectorAdmissionProvider<'a,S:RetireOwned+Sync>=super::child_editor::read::admission::QualifiedChildAdmissionProvider<'a,S,ChildReadStamp>;
impl<'a,S:RetireOwned+::semio_os_kernel::StoreState> super::child_editor::read::admission::QualifiedChildAdmissionProvider<'a,S,ChildReadStamp>{pub fn admit(custody:&'a ChildReadSourceCustody<S>,registration:&'static ChildVectorReadRegistration<S>,ordinal:usize,g:RetainedCloneGrant)->Result<(Self,RetainedCloneProgress),ValueError>{if !retained_clone_grant_admits(g,Self::demand()){return Err(refusal("Qualified child admission provider birth is unfunded"))}if custody.stamp().is_some_and(|stamp|stamp.ordinal()!=ordinal){return Err(refusal("Original vector provider ordinal differs from its qualified reference").with_retained_progress(RetainedCloneProgress{copied_items:1,copied_bytes:Self::demand().copy_bytes-ChildAdmissionAddress::demand().copy_bytes,..Default::default()}))}Self::admit_registered(custody,&registration.native.identity as*const _ as usize,registration.admission,registration.vector,ordinal,g)}}
